                        if (_gO->IsA(_cChr)) AllChars.push_back(static_cast<AOrionChar*>(_gO));
                        if (_gO->IsA(_cTwr)) AllTowers.push_back(static_cast<AOrionDamageableObjective_Base*>(_gO));
