                                    bool pdyWasBlind = (BotIsBlind.count(bot) && BotIsBlind[bot]);
                                    if (pdyPred && pdyOutside && pdyInCap) g_pdyStreak[bot] = (g_pdyStreak.count(bot) ? g_pdyStreak[bot] : 0) + 1;
